var s = 10, ids = ['rel', 'freq', 'sign', 'time'];
for (var i = 0; i < ids.length; i++) s += (+v(ids[i]) || 0);
s = Math.max(3, Math.min(95, s));
Crowd.lottery(el, { n: 100, p: s / 100, rounds: 1,
  title: '100人がこの条件で告白したら',
  roundLabel: function () { return '告白の結果'; },
  final: function (w, n, you) { return '100人のうち ' + w + '人が成功（成功率 ' + s + '%）。このシミュでは、あなたは' + (you ? '成功！' : '今回はうまくいかず…'); } });
